// Jeebis terminal application recognition regressions.
const assert = require("node:assert/strict")
const fs = require("node:fs")
const vm = require("node:vm")
const path = require("node:path")
const context = vm.createContext({})
vm.runInContext(fs.readFileSync(path.join(__dirname, "../../bars/widgets/ruixen.apps/AppIdentity.js"), "utf8"), context)
function client(appId, title) { return { wayland: { appId }, title } }
assert.equal(context.terminalApplication(client("TUI.float", "Yazi: jeebis")), "yazi")
assert.equal(context.terminalApplication(client("TUI", "Yazi: /tmp")), "yazi")
assert.equal(context.terminalApplication({lastIpcObject: {class: "TUI.float"}, title: "Yazi: jeebis"}), "yazi")
assert.equal(context.terminalApplication(client("TUI.float", "btop")), "")
assert.equal(context.terminalApplication(client("firefox", "Yazi: documentation")), "")
assert.equal(context.terminalApplication(client("wezterm", "Yazi · WezTerm — files")), "yazi")
assert.equal(context.terminalApplication(client("wezterm", "Codex · WezTerm — agent")), "codex")
assert.equal(context.terminalApplication(client("wezterm", "Neovim · WezTerm — file")), "nvim")
assert.equal(context.applicationIdentity(client("TUI.float", "Yazi: jeebis")), context.applicationIdentity(client("wezterm", "Yazi · WezTerm — files")))
assert.equal(context.terminalApplication(client("org.omarchy.codex", "Codex")), "codex")
assert.equal(context.applicationIdentity(client("org.omarchy.codex", "agent")), "rio:codex")
assert.equal(context.terminalApplication(client("com.raphamorim.rio", "Yazi: documentation")), "")
assert.equal(context.terminalApplication(null), "")
console.log("JeebisAppIdentity: 13 assertions passed")
